/* G40-549 — what each request card on the home screen says.
 *
 * One card per live request: a pill, a title, ONE status sentence and a
 * right-hand label naming where the tap goes. Every word comes from fields
 * GET /orders/v3 already returns; the tap itself is unchanged
 * (requestHeader.js getOrderbyId).
 *
 * Colour follows John's general practice (2026-10-04, 19:37 ET): "the green
 * with container pulse is good and red with container pulse is bad. so in the
 * doc you sent, only a failed payment is red".
 *   good  = good news the requester acts on: green + pulse
 *   bad   = a failed payment: red + pulse
 *   calm  = nothing to do
 *   sched = booked for later
 *   hold  = an open dispute (requester and worker): grey, no pulse ("grey dispute is fine")
 *
 * No arrival time: the server has the Gopher's position but no travel ETA.
 * No offer counts: requestor_alerts counts only UNVIEWED offers. */

import { disputeResolution } from "../../helpers/disputeState.js";
import {
  categoryLabel,
  customTaskText,
  requestTitleLabel,
} from "../../helpers/categoryLabel.js";
import { photoStepUnresolved } from "../../helpers/photoStep.js";
