/* The web's Step-1 photos (Code main assets/img), by stored category. */
const PHOTO_BY_CATEGORY = {
  Delivery: "delivery.webp",
  "Need a Ride": "ride.webp",
  Moving: "moving.webp",
  "Junk Removal": "junk.webp",
  "Home Services": "home-services.webp",
  "Hourly / Day Labor": "labor.jpg",
  "Yard Project": "yard.webp",
  Other: "custom-task.webp",
};
export const categoryPhoto = (category) =>
  `/assets_1/home/${PHOTO_BY_CATEGORY[category] || PHOTO_BY_CATEGORY.Other}`;

const alertCount = (item, key) => Number(item?.requestor_alerts?.[key] || 0);

const gopherName = (item) =>
  (item?.gopher?.first_name || "").trim() || "Your worker";

/* "Delivery · 405 Shorehouse Way". With no address, today's identifier line
   (G40-551): the typed Custom Task name, else the stored title as people
   read it ("Yard Project", "Moving - Other"). */
export function cardTitle(item) {
  const name = categoryLabel(item?.category_type) || "Request";
  const line = item?.address?.line1 || item?.dropoff_address?.line1;
  if (line) return `${name} · ${line}`;
  if (item?.category_type === "Other") {
    return customTaskText(item.title) || categoryLabel("Other");
  }
  return requestTitleLabel(item?.title) || name;
}

/* "open for 42 more min" / "open for about 3 more hours", from delivery_eta.
   Nothing once it has passed: an order can stay open past it while offers
   are out (middleware/crons.js), so we never say "expired". */
export function openFor(item, now = Date.now()) {
  const eta = item?.delivery_eta ? new Date(item.delivery_eta).getTime() : NaN;
  if (!Number.isFinite(eta)) return "";
  const min = Math.round((eta - now) / 60000);
  if (min <= 0) return "";
  if (min < 60) return `open for ${min} more min`;
  const hours = Math.round(min / 60);
  return hours === 1
    ? "open for about 1 more hour"
    : `open for about ${hours} more hours`;
}

export function scheduleWords(item) {
  if (!item?.request_schedule_time) return "";
  const d = new Date(item.request_schedule_time);
  if (Number.isNaN(d.getTime())) return "";
  const day = d.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
  });
  const time = d.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
  });
  return `${day} · ${time}`;
}

const isScheduledList = (item) =>
  Boolean(item?.request_schedule_later) &&
  ["pending", "scheduled"].includes(item?.aasm_state);

/** The words and colour for one order. */
/* G40-549 G5: when an expired request was open until — "4:30 PM" today,
   "Oct 9" before that. From delivery_eta (the time the request was open
   until); nothing when it is missing or unparseable. */
export function endedWords(item, now = Date.now()) {
  const t = item?.delivery_eta ? new Date(item.delivery_eta) : null;
  if (!t || !Number.isFinite(t.getTime())) return "";
  const today = new Date(now);
  const sameDay =
    t.getFullYear() === today.getFullYear() &&
    t.getMonth() === today.getMonth() &&
    t.getDate() === today.getDate();
  return sameDay
    ? t.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })
    : t.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

/* G40-549 G5: which expired requests Home still shows — the ones that ended
   in the last day. Ended = delivery_eta (open until), or updated_at (the
   expiry stamp) when that is missing. */
export const RECENT_EXPIRED_MS = 24 * 60 * 60 * 1000;
export function recentlyExpired(rows, now = Date.now()) {
  return (rows || []).filter((r) => {
    if (r?.aasm_state !== "expired") return false;
    const at = new Date(r.delivery_eta || r.updated_at || NaN).getTime();
    return (
      Number.isFinite(at) && now - at >= 0 && now - at <= RECENT_EXPIRED_MS
    );
  });
}

export function cardModel(item, now = Date.now()) {
  const name = gopherName(item);
  const base = {
    id: item?.id,
    title: cardTitle(item),
    photo: categoryPhoto(item?.category_type),
    gopherPhoto: item?.gopher_id
      ? item?.gopher?.profile_photo || item?.gopher?.business_logo || ""
      : "",
  };

  /* G40-549 G5 (John, 10/10 7:57 AM ET: G5 = B): a request that expired
     with no Gopher stays on Home, grey (nothing failed, it ended), and opens
     the "No Gopher took this request" page. requestHeader adds these from
     Request History's own query (statuses[]=expired), recent ones only. */
  if (item?.aasm_state === "expired") {
    const ended = endedWords(item, now);
    return {
      ...base,
      kind: "ended",
      pill: "NO WORKER FOUND",
      status: ended ? `Ended ${ended} · tap for options` : "Tap for options",
      go: "View ›",
    };
  }
  if (item?.payment_status === "requires_payment_method") {
    return {
      ...base,
      kind: "bad",
      pill: "PAYMENT FAILED",
      /* G40-607: name who declined when the order says (Stage 1 pick A). */
      status:
        declineHomeStatus(declineReasonFrom(item?.stripe_error)) ||
        "Your card was declined · update payment info",
      go: "Update →",
    };
  }
  /* John, 10/11: "The dispute is NOT with our team. Disputes are between a
     customer and a worker." The card follows the dispute's own timeline
     (live/DisputeViews.js): the worker makes it right; Gopher support steps
     in only once the requester taps "Unable to resolve" (unable_to_dispute). */
  /* G40-549 (John 10/12): once Gopher support decides it in HQ the dispute
     is over. Paid → "rate them"; otherwise just closed. Grey, no pulse. */
  if (disputeResolution(item)) {
    return {
      ...base,
      kind: "hold",
      pill: "RESOLVED",
      status:
        disputeResolution(item) === "paid_worker"
          ? `Gopher support paid ${name} · rate them`
          : "Gopher support closed this dispute",
      go: "View ›",
    };
  }
  if (item?.disputed) {
    return {
      ...base,
      kind: "hold",
      pill: "DISPUTE OPEN",
      status: item?.unable_to_dispute
        ? "Gopher support is stepping in"
        : `${name} is making it right`,
      go: "View ›",
    };
  }
  if (alertCount(item, "order_gophers") > 0 || alertCount(item, "bids") > 0) {
    return {
      ...base,
      kind: "good",
      pill: "NEEDS YOU",
      status: "New offers from workers · choose one",
      go: "Review →",
    };
  }
  if (alertCount(item, "counter") > 0) {
    return {
      ...base,
      kind: "good",
      pill: "NEEDS YOU",
      status: "A worker sent a counter-offer",
      go: "Review →",
    };
  }
  if (alertCount(item, "cogs") > 0) {
    return {
      ...base,
      kind: "good",
      pill: "NEEDS YOU",
      /* John 10/10: keep it general -- the adjustment may be the offer, not
         the items. */
      status: "Cost adjustment approval needed",
      go: "Approve →",
    };
  }
  if (alertCount(item, "re_scheduled_request") > 0) {
    return {
      ...base,
      kind: "good",
      pill: "NEEDS YOU",
      status: `${name} asked for a new time`,
      go: "Review →",
    };
  }
  if (item?.aasm_state === "delivered") {
    /* G40-39: confirm only once the photo step is resolved. */
    return photoStepUnresolved(item)
      ? {
          ...base,
          kind: "calm",
          pill: "WRAPPING UP",
          status: `${name} marked it complete`,
          go: "View ›",
        }
      : {
          ...base,
          kind: "good",
          pill: "NEEDS YOU",
          status: `${name} marked it complete · confirm or dispute`,
          go: "Confirm →",
        };
  }
  if (isScheduledList(item)) {
    const when = scheduleWords(item);
    return {
      ...base,
      kind: "sched",
      pill: "SCHEDULED",
      status: [when, "waiting for a worker"].filter(Boolean).join(" · "),
      go: "View ›",
    };
  }
  if (item?.aasm_state === "accepted" && item?.request_schedule_later) {
    const when = scheduleWords(item);
    return {
      ...base,
      kind: "sched",
      pill: "SCHEDULED",
      status: [when, `with ${name}`].filter(Boolean).join(" · "),
      go: "View ›",
    };
  }
  if (item?.aasm_state === "accepted") {
    const rating = Number(item?.gopher?.average_rating);
    const stars =
      Number(item?.gopher?.total_ratings) > 0 && rating > 0
        ? ` · ★ ${rating.toFixed(1)}`
        : "";
    return {
      ...base,
      kind: "calm",
      pill: "ACCEPTED",
      status: `${name} accepted${stars}`,
      go: "Track ›",
    };
  }
  if (item?.aasm_state === "picked_up") {
    return {
      ...base,
      kind: "calm",
      pill: "IN PROGRESS",
      status: `${name} is on the job`,
      go: "Track ›",
    };
  }
  if (item?.aasm_state === "purchased") {
    return {
      ...base,
      kind: "calm",
      pill: "ON THE WAY",
      status: `${name} has your items and is on the way`,
      go: "Track ›",
    };
  }
  /* pending, Need ASAP */
  return {
    ...base,
    kind: "calm",
    pill: "SUBMITTED",
    status: ["Looking for your worker…", openFor(item, now)]
      .filter(Boolean)
      .join(" · "),
    go: "View ›",
    looking: true,
  };
}

/* John, 20:29 ET 10/4: "order is good" — cards that need you first (a failed
   payment, then good news), then live, then scheduled; newest first in each. */
const RANK = { bad: 0, good: 1, calm: 2, hold: 2, sched: 3, ended: 4 };
export function orderCards(items, now = Date.now()) {
  return items
    .map((item) => ({ item, card: cardModel(item, now) }))
    .sort(
      (a, b) =>
        RANK[a.card.kind] - RANK[b.card.kind] ||
        Number(b.item?.id || 0) - Number(a.item?.id || 0),
    );
}

/* "You have 2 current requests, 1 needs you". The count is green unless every
   card that needs you is a failed payment. */
export function headline(cards) {
  /* G40-549 G5: an ended request (no Gopher found) is not a current one. */
  const ended = cards.filter(({ card }) => card.kind === "ended").length;
  const n = cards.length - ended;
  if (n === 0 && ended > 0) {
    return {
      lead:
        ended === 1
          ? "Your request ended with no worker"
          : `${ended} requests ended with no worker`,
      attention: "",
      attentionBad: false,
    };
  }
  const needs = cards.filter(
    ({ card }) => card.kind === "good" || card.kind === "bad",
  );
  return {
    lead: `You have ${n} current request${n === 1 ? "" : "s"}`,
    attention: needs.length
      ? `${needs.length} need${needs.length === 1 ? "s" : ""} you`
      : "",
    attentionBad:
      needs.length > 0 && needs.every(({ card }) => card.kind === "bad"),
  };
}
